      SUBROUTINE SEXT2CC     CALCULATES SECOND-ORDER TRANSFER MATRIX FOR A SEXTUPOLEC      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM4C.CIN'      INCLUDE 'T.CIN'C-------------------------------------------------------------------------------C      W2 = 2.*K2      S = - 0.25*W2*L      T(1,1) = S*L      T(2,1) = 2.0*S      S  =  - W2*L**3/24.      T(1,3) = S*L      T(2,3) = 4.0*S      S = 0.25*W2*L      T(1,6) = S*L      T(2,6) = 2.0*S      S = W2*L**3/24.      T(1,10) = S*L      T(2,10) = 4.0*S      S = - W2*L**2/6.      T(1,2) = S*L      T(2,2) = 3.0*S      S = W2*L**2/6.      T(1,9) = S*L      T(2,9) = 3.0*S      S = W2*L/2.      T(3,4) = S*L      T(4,4) = 2.0*S      S = W2*L**2/6.      T(3,5) = S*L      T(3,7) = S *L      T(4,5) = 3.0*S      T(4,7) = 3.0*S      S = W2*L**3/12.      T(3,8) = S*L      T(4,8) = 4.0*S      T(5,3) = - 0.5*L      T(5,10) = - 0.5*L      RETURN      END